using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "RoyalScarabOmenData", menuName = "Data/Battle/Omens System/Omen Data/Sothis/RoyalScarabOmenData")]
public class RoyalScarabOmenData : EndOfTurnOmenData
{
	[Header("Royal Scarab Omen Data")]
	[SerializeField]
	protected CurrentCompanions currentCompanions;

	[SerializeField]
	private EffectsList effectsList;

	protected override Action GetOmenCheckActivationAction(OmenInstance omenInstance)
	{
		return delegate
		{
			if (currentCompanions.IsCompanionsWithAfflictionGetAmount() != 0)
			{
				ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.EndOfTurnOmenActions.Add(GetOmenAction(omenInstance));
			}
		};
	}

	public override Action GetOmenAction(OmenInstance omenInstance)
	{
		return delegate
		{
			int num = currentCompanions.IsCompanionsWithAfflictionGetAmount();
			omenInstance.ActivateOmenFeedback();
			OmenLogic.ActivateOmen(null, num * ActionValue, null, null, CorruptionPurifyModifierEnum.NONE, playSFX: true);
		};
	}

	public override string OmenConvertedDescription()
	{
		string text = Smart.Format(base.localizationManager.GetLocalizedForEach(), GetOmenConvertedDescriptionBattleAction().RemoveLastIfNotJapaneseNorKoreanNorTraditionalChinese(), base.localizationManager.GetLocalizedEffectSentinelsHaveFormatted(effectsList.AfflictionEffect));
		return GetEndOfPlayerTurnLocalizedDescription() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + text;
	}
}
